// ---------------------------------------------------------------------------
// Normalize Request
// Validates the form input and produces a single `config` object that every
// downstream node reads. All defaults live here -- change them here only.
// ---------------------------------------------------------------------------
const form = $input.first().json || {};

const get = (...keys) => {
  for (const k of keys) {
    const v = form[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return '';
};

const int = (raw, dflt, min, max) => {
  const n = Number(raw);
  if (!Number.isFinite(n) || n <= 0) return dflt;
  return Math.min(Math.max(Math.round(n), min), max);
};

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const recipientsRaw = get('Recipient Email(s)', 'recipientEmails', 'recipients');
const recipients = recipientsRaw
  .split(/[,;]/)
  .map((e) => e.trim().toLowerCase())
  .filter((e) => e.length > 0);

if (recipients.length === 0) {
  throw new Error('At least one recipient email is required.');
}
const bad = recipients.filter((e) => !EMAIL_RE.test(e));
if (bad.length) {
  throw new Error('Invalid recipient email(s): ' + bad.join(', '));
}

// Roster match patterns: comma separated, lowercased, %-wrapped if needed.
const rosterRaw = get('Roster Team Match', 'rosterTeamMatch');
const toPattern = (s) => {
  const t = s.trim().toLowerCase();
  if (!t) return '';
  return t.includes('%') ? t : '%' + t + '%';
};
const rosterTeamPatterns = (rosterRaw
  ? rosterRaw.split(',').map(toPattern).filter(Boolean)
  : ['%multi%contact%', '%specialized%supervisor%']);

const runTranscriptAnalysis =
  get('Run Transcript Analysis', 'runTranscriptAnalysis').toLowerCase() !== 'no';

const lookbackDays = int(get('Lookback Days', 'lookbackDays'), 90, 7, 400);
const today = new Date();
const windowEnd = today.toISOString().slice(0, 10);
const windowStart = new Date(today.getTime() - lookbackDays * 86400000)
  .toISOString().slice(0, 10);

const config = {
  requestId: 'mc-escalations-' + Date.now(),
  submittedAt: new Date().toISOString(),
  requestedBy: get('Requested By (email)', 'requestedBy') || recipients[0],
  recipientEmails: recipients,
  recipientEmail: recipients.join(','),

  // ---- window ----
  lookbackDays,
  windowStart,
  windowEnd,
  reportPeriodLabel: windowStart + ' to ' + windowEnd + ' (' + lookbackDays + ' days)',

  // ---- population definition (validate with sql/00_discovery_labels.sql) ----
  rosterTeamPatterns,
  escalationDetailPatterns: [
    '%escalated by agent%',
    '%escalation resolved by supervisor%',
    '%escalation transferred to tier%'
  ],
  queuePatterns: ['%multi contact%', '%care%'],
  naRegionOnly: true,

  // ---- volumes / cost guards ----
  maxDetailRows: int(get('Max Detail Rows', 'maxDetailRows'), 50000, 100, 200000),
  perJourneySample: int(get('Transcripts Per Journey', 'perJourneySample'), 8, 1, 50),
  maxTotalSample: int(get('Max Transcripts Total', 'maxTotalSample'), 120, 1, 400),
  maxTranscriptChars: 12000,
  minUtterances: 12,
  transcriptsPerLlmCall: 5,

  // ---- LLM ----
  runTranscriptAnalysis,
  model: 'claude-opus-5',
  maxTokens: 16000,

  // ---- tables (single source of truth) ----
  tables: {
    wrap: 'wf-gcp-us-service-data-prod.omnichannel_public.tbl_service_contact_wrap',
    employee: 'wf-gcp-us-ae-gat-prod.ops_reporting_core.tbl_snapshot_dim_employee',
    datamart: 'wf-gcp-us-ae-gat-prod.ops_reporting.tbl_datamart_service_performance_metrics',
    laiPipeline: 'wf-gcp-us-ae-cs-prod.gsat_reporting.lai_pipeline_data',
    utterances:
      'wf-gcp-us-cust-conv-proc-prod.post_order_level_ai_import.conversation_speaker_utterances'
  },
  levelAiUrlPrefix: 'https://wayfair.thelevel.ai/organizations/2/conversations/review/'
};

return [{ json: { config } }];

// ---------------------------------------------------------------------------
// Summarize Escalations
// Turns the escalation detail rows into the quantitative half of the report:
// volume, journey mix, queue split, monthly trend, resolution rate, and the
// transcript coverage that bounds the qualitative half.
// ---------------------------------------------------------------------------
const cfg = $('Normalize Request').first().json.config;
const rows = $input.all()
  .map((i) => i.json)
  .filter((r) => r && r.wrap_id !== undefined && r.wrap_id !== null);

const tally = (list, keyFn) => {
  const m = new Map();
  for (const r of list) {
    const k = keyFn(r) || 'Unknown';
    m.set(k, (m.get(k) || 0) + 1);
  }
  return m;
};

const toSorted = (map, total) =>
  [...map.entries()]
    .map(([key, count]) => ({
      key,
      count,
      pct: total ? Math.round((count / total) * 1000) / 10 : 0
    }))
    .sort((a, b) => b.count - a.count);

const total = rows.length;
const truthy = (v) => v === true || v === 'true' || v === 1 || v === '1';

const journeyMap = new Map();
for (const r of rows) {
  const k = r.journey || 'Unclassified';
  const e = journeyMap.get(k) || { journey: k, count: 0, resolved: 0, withTranscript: 0, orders: new Set() };
  e.count += 1;
  if (truthy(r.is_customer_issue_resolved)) e.resolved += 1;
  if (truthy(r.has_transcript_handle)) e.withTranscript += 1;
  if (r.order_number_final) e.orders.add(String(r.order_number_final));
  journeyMap.set(k, e);
}

const byJourney = [...journeyMap.values()]
  .map((e) => ({
    journey: e.journey,
    count: e.count,
    pct: total ? Math.round((e.count / total) * 1000) / 10 : 0,
    resolvedInContactPct: e.count ? Math.round((e.resolved / e.count) * 1000) / 10 : 0,
    transcriptCoveragePct: e.count ? Math.round((e.withTranscript / e.count) * 1000) / 10 : 0,
    distinctOrders: e.orders.size
  }))
  .sort((a, b) => b.count - a.count);

const byMonth = toSorted(tally(rows, (r) => r.wrap_month), total)
  .sort((a, b) => String(a.key).localeCompare(String(b.key)));

const agentMap = tally(rows, (r) => r.mc_agent_name);
const withTranscript = rows.filter((r) => truthy(r.has_transcript_handle)).length;
const resolvedCount = rows.filter((r) => truthy(r.is_customer_issue_resolved)).length;

const summary = {
  totalEscalations: total,
  distinctOrders: new Set(rows.map((r) => r.order_number_final).filter(Boolean)).size,
  distinctMcAgents: agentMap.size,
  resolvedInContactPct: total ? Math.round((resolvedCount / total) * 1000) / 10 : 0,
  transcriptCoveragePct: total ? Math.round((withTranscript / total) * 1000) / 10 : 0,
  escalationsWithTranscript: withTranscript,
  avgPerDay: total ? Math.round((total / cfg.lookbackDays) * 10) / 10 : 0,
  byJourney,
  byQueueGroup: toSorted(tally(rows, (r) => r.queue_group), total),
  byDetailReason: toSorted(tally(rows, (r) => r.escalation_detail_reason), total),
  byChannel: toSorted(tally(rows, (r) => r.wrap_contact_channel), total),
  byMonth,
  bySite: toSorted(tally(rows, (r) => r.mc_site), total).slice(0, 10),
  byManager: toSorted(tally(rows, (r) => r.mc_manager_name), total).slice(0, 15),
  topAgentsByVolume: toSorted(agentMap, total).slice(0, 15),
  dataQuality: {
    unmappedQueuePct: total
      ? Math.round((rows.filter((r) => r.queue_group === 'Other / Unmapped').length / total) * 1000) / 10
      : 0,
    unclassifiedJourneyPct: total
      ? Math.round((rows.filter((r) => (r.journey || '') === 'Unclassified').length / total) * 1000) / 10
      : 0,
    automatedWrapPct: total
      ? Math.round((rows.filter((r) => truthy(r.is_automated_wrap)).length / total) * 1000) / 10
      : 0
  }
};

return [{ json: { config: cfg, summary } }];

// ---------------------------------------------------------------------------
// Batch Transcripts
// Groups sampled transcripts into one item per LLM call.
// ---------------------------------------------------------------------------
const cfg = $('Normalize Request').first().json.config;
const calls = $input.all()
  .map((i) => i.json)
  .filter((r) => r && r.transcript_text && String(r.transcript_text).trim().length > 0);

if (calls.length === 0) {
  return [{ json: { config: cfg, batchIndex: 0, calls: [], empty: true } }];
}

const size = Math.max(1, Number(cfg.transcriptsPerLlmCall) || 5);
const out = [];
for (let i = 0; i < calls.length; i += size) {
  out.push({
    json: {
      config: cfg,
      batchIndex: out.length,
      batchCount: Math.ceil(calls.length / size),
      sampledTotal: calls.length,
      calls: calls.slice(i, i + size)
    }
  });
}
return out;

// ---------------------------------------------------------------------------
// Build Claude Request
// Assembles one Messages API request per batch. Structured output guarantees
// the classification shape. Canonical prompt copy: prompts/escalation_extraction.md
// ---------------------------------------------------------------------------
const item = $input.item.json;
const cfg = item.config;
const calls = item.calls || [];

const SYSTEM_PROMPT = [
  "You analyze customer service call transcripts for Wayfair's North America",
  'Multi-Contact (MC) / CARE escalation team. Each transcript is an escalated',
  'phone call: a frontline agent transferred an unhappy customer to an MC agent',
  'or Specialized Supervisor, or the customer reached the escalation queue directly.',
  '',
  'Your job is to extract, per call, (a) what triggered the escalation, (b) what the',
  'customer asked for, (c) what the agent actually provided, and (d) whether the',
  'issue was closed in that contact.',
  '',
  'Rules:',
  '1. Extract only what the transcript supports. If a field is not evidenced, use',
  '   "not_stated" or null rather than inferring. Do not speculate about intent.',
  '2. Transcripts are ASR output: expect misrecognized words, missing turns, and',
  '   speaker-label errors. Judge on meaning, not exact wording.',
  '3. Use the closed enum values exactly as given. Anything that does not fit goes',
  '   to "other", described in the matching free-text field.',
  '4. Redact personal data in every free-text field and quote: no customer or agent',
  '   names, phone numbers, addresses, emails, order numbers, or payment details.',
  '   Write [REDACTED] in their place.',
  '5. Quotes must be verbatim customer speech, at most 200 characters, free of',
  '   personal data. If no clean quote exists, return null.',
  '6. "customer_ask" is what the customer wanted at the point of escalation, not',
  '   what they settled for. "agent_provided" is what the MC agent actually',
  '   committed to on the call.',
  '7. Return exactly one object per input call, in input order, keyed by the',
  '   contact_id given to you.'
].join('\n');

const RESPONSE_SCHEMA = {
  type: 'object',
  properties: {
    classifications: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          contact_id: { type: 'string' },
          journey_observed: {
            type: 'string',
            enum: ['delivery_shipping', 'damaged_defective', 'missing_item_parts', 'returns',
                   'replacements_rap', 'cancellation', 'billing_credits_refund',
                   'assembly_service', 'warranty_protection_plan', 'order_placement_change',
                   'fraud_account_security', 'agent_service_experience', 'other', 'not_stated']
          },
          escalation_trigger: {
            type: 'string',
            enum: ['repeat_contact_unresolved', 'delivery_delay_or_missed_window',
                   'damaged_or_defective_item', 'missing_item_or_parts', 'refund_not_received',
                   'billing_or_charge_dispute', 'return_or_pickup_failure',
                   'replacement_or_parts_delay', 'cancellation_problem', 'policy_denial',
                   'resolution_reversed_or_broken_promise', 'agent_conduct_or_communication',
                   'wait_time_or_transfers', 'supplier_or_third_party_failure',
                   'system_or_tool_failure', 'customer_requested_supervisor_only',
                   'other', 'not_stated']
          },
          escalation_trigger_detail: { type: ['string', 'null'] },
          customer_ask_primary: {
            type: 'string',
            enum: ['full_refund', 'partial_refund_or_discount', 'replacement_unit',
                   'replacement_parts', 'expedited_delivery', 'firm_delivery_date',
                   'return_pickup', 'fee_waiver', 'cancel_order', 'keep_item_and_refund',
                   'supervisor_or_executive_contact', 'apology_or_accountability',
                   'callback_commitment', 'information_or_status_only', 'other', 'not_stated']
          },
          customer_ask_secondary: { type: ['string', 'null'] },
          agent_provided_primary: {
            type: 'string',
            enum: ['full_refund', 'partial_refund_or_credit', 'replacement_order',
                   'replacement_parts', 'expedited_reship', 'delivery_escalation_ticket',
                   'return_label_or_pickup', 'fee_waiver', 'cancellation_processed',
                   'keep_item_and_refund', 'ticket_to_another_team',
                   'policy_explanation_no_remedy', 'callback_or_follow_up_promised',
                   'transferred_to_tier_ii', 'no_resolution_offered', 'other', 'not_stated']
          },
          agent_provided_detail: { type: ['string', 'null'] },
          ask_met: { type: 'string', enum: ['fully_met', 'partially_met', 'not_met', 'unclear'] },
          resolution_status: {
            type: 'string',
            enum: ['resolved_in_contact', 'pending_follow_up', 'transferred', 'unresolved',
                   'customer_disconnected', 'unclear']
          },
          concession_given: { type: 'boolean' },
          repeat_contacts_mentioned: { type: ['integer', 'null'] },
          blocker: {
            type: 'string',
            enum: ['none', 'policy_limit', 'system_or_tool_limit', 'wizard_no_resolution',
                   'supplier_or_carrier_dependency', 'approval_or_authority_limit',
                   'prior_agent_error', 'customer_expectation_gap', 'other']
          },
          blocker_detail: { type: ['string', 'null'] },
          de_escalation_behaviors: {
            type: 'array',
            items: {
              type: 'string',
              enum: ['empathy_acknowledgment', 'ownership_statement', 'clear_next_steps',
                     'specific_timeline_given', 'recap_confirmation', 'none_observed']
            }
          },
          further_contact_risk: { type: 'string', enum: ['low', 'medium', 'high'] },
          further_contact_risk_reason: { type: ['string', 'null'] },
          customer_quote: { type: ['string', 'null'] },
          coaching_theme: { type: ['string', 'null'] },
          confidence: { type: 'number' }
        },
        required: ['contact_id', 'journey_observed', 'escalation_trigger',
                   'customer_ask_primary', 'agent_provided_primary', 'ask_met',
                   'resolution_status', 'concession_given', 'blocker',
                   'de_escalation_behaviors', 'further_contact_risk', 'confidence'],
        additionalProperties: false
      }
    }
  },
  required: ['classifications'],
  additionalProperties: false
};

const userText = [
  'Analyze the following ' + calls.length + ' escalated calls. Return one',
  'classification object per call, in input order.',
  ''
].concat(
  calls.map((c, idx) =>
    [
      '--- CALL ' + (idx + 1) + ' ---',
      'contact_id: ' + c.contact_id,
      'wrap_journey (agent-selected primary reason): ' + (c.journey || 'Unclassified'),
      'wrap_detail_reason: ' + (c.escalation_detail_reason || 'not_stated'),
      'issue_marked_resolved_by_agent: ' + String(c.is_customer_issue_resolved),
      'transcript_truncated: ' + String(c.transcript_truncated),
      'transcript:',
      String(c.transcript_text || '').trim(),
      ''
    ].join('\n')
  )
).join('\n');

const requestBody = {
  model: cfg.model,
  max_tokens: cfg.maxTokens,
  thinking: { type: 'adaptive' },
  output_config: { format: { type: 'json_schema', schema: RESPONSE_SCHEMA } },
  system: [{ type: 'text', text: SYSTEM_PROMPT, cache_control: { type: 'ephemeral' } }],
  messages: [{ role: 'user', content: userText }]
};

return {
  json: {
    config: cfg,
    batchIndex: item.batchIndex,
    batchCount: item.batchCount,
    contactIds: calls.map((c) => c.contact_id),
    requestBody
  }
};

// ---------------------------------------------------------------------------
// Parse Classifications
// Reads the Messages API responses, validates the structured payload, and
// re-attaches BigQuery context to each classification. Batch-level failures
// are recorded, never thrown, so one bad batch cannot lose the whole run.
// ---------------------------------------------------------------------------
const cfg = $('Normalize Request').first().json.config;

// contact_id -> sampled BigQuery row (journey, links, agent, dates)
const sampleById = new Map();
for (const it of $('GBQ: Transcript Sample').all()) {
  const r = it.json || {};
  if (r.contact_id) sampleById.set(String(r.contact_id), r);
}

const out = [];
const errors = [];

$input.all().forEach((item, i) => {
  const resp = item.json || {};
  const ctx = (() => {
    try { return $('Build Claude Request').all()[i].json; } catch (e) { return {}; }
  })();

  if (resp.stop_reason === 'refusal') {
    errors.push({ batchIndex: ctx.batchIndex, reason: 'model_refusal',
                  detail: JSON.stringify(resp.stop_details || {}) });
    return;
  }

  const blocks = Array.isArray(resp.content) ? resp.content : [];
  const text = blocks.filter((b) => b && b.type === 'text').map((b) => b.text).join('');
  if (!text) {
    errors.push({ batchIndex: ctx.batchIndex, reason: 'no_text_block',
                  detail: (resp.error && resp.error.message) || 'empty response' });
    return;
  }

  let parsed;
  try {
    parsed = JSON.parse(text);
  } catch (e) {
    errors.push({ batchIndex: ctx.batchIndex, reason: 'json_parse_failed',
                  detail: String(e.message).slice(0, 200) });
    return;
  }

  const list = Array.isArray(parsed.classifications) ? parsed.classifications : [];
  list.forEach((c) => {
    const src = sampleById.get(String(c.contact_id)) || {};
    out.push({
      json: Object.assign({}, c, {
        journey_wrap: src.journey || 'Unclassified',
        wrap_id: src.wrap_id || null,
        wrap_datetime: src.wrap_datetime || null,
        mc_agent_name: src.mc_agent_name || null,
        order_number: src.order_number || null,
        levelai_url: src.levelai_url || null,
        utterance_count: src.utterance_count || null,
        transcript_truncated: src.transcript_truncated || false,
        journey_agrees: (src.journey || '').length > 0 &&
          String(src.journey).toLowerCase().replace(/[^a-z]/g, '')
            .includes(String(c.journey_observed || '').split('_')[0]),
        input_tokens: (resp.usage && resp.usage.input_tokens) || null,
        output_tokens: (resp.usage && resp.usage.output_tokens) || null,
        batchIndex: ctx.batchIndex
      })
    });
  });
});

if (out.length === 0) {
  return [{ json: { config: cfg, classificationErrors: errors, empty: true } }];
}
out.push({ json: { config: cfg, classificationErrors: errors, isErrorSummary: true } });
return out;

// ---------------------------------------------------------------------------
// Roll Up Insights
// Aggregates the per-call classifications into the qualitative half of the
// report: escalation drivers, customer asks, agent responses, ask-met rate,
// blockers, and a customer-ask x agent-response cross-tab per journey.
// ---------------------------------------------------------------------------
const cfg = $('Normalize Request').first().json.config;
const items = $input.all().map((i) => i.json);
const errorRow = items.find((r) => r && r.isErrorSummary);
const classifications = items.filter((r) => r && r.contact_id && !r.isErrorSummary);

const label = (v) =>
  String(v || 'not_stated').replace(/_/g, ' ').replace(/\b\w/g, (m) => m.toUpperCase());

const rank = (arr, keyFn, limit) => {
  const m = new Map();
  for (const c of arr) {
    const k = keyFn(c);
    if (k === undefined || k === null || k === '') continue;
    m.set(k, (m.get(k) || 0) + 1);
  }
  const total = arr.length;
  return [...m.entries()]
    .map(([key, count]) => ({
      key,
      label: label(key),
      count,
      pct: total ? Math.round((count / total) * 1000) / 10 : 0
    }))
    .sort((a, b) => b.count - a.count)
    .slice(0, limit || 999);
};

const n = classifications.length;

// Per-journey view, driven by the agent-selected wrap journey (authoritative).
const journeys = new Map();
for (const c of classifications) {
  const k = c.journey_wrap || 'Unclassified';
  const e = journeys.get(k) || { journey: k, calls: [] };
  e.calls.push(c);
  journeys.set(k, e);
}

const byJourney = [...journeys.values()]
  .map((e) => {
    const calls = e.calls;
    const met = calls.filter((c) => c.ask_met === 'fully_met').length;
    const partial = calls.filter((c) => c.ask_met === 'partially_met').length;
    const resolved = calls.filter((c) => c.resolution_status === 'resolved_in_contact').length;
    const highRisk = calls.filter((c) => c.further_contact_risk === 'high').length;
    const quotes = calls.map((c) => c.customer_quote).filter(Boolean).slice(0, 3);
    return {
      journey: e.journey,
      sampledCalls: calls.length,
      topTriggers: rank(calls, (c) => c.escalation_trigger, 3),
      topCustomerAsks: rank(calls, (c) => c.customer_ask_primary, 3),
      topAgentProvided: rank(calls, (c) => c.agent_provided_primary, 3),
      topBlockers: rank(calls.filter((c) => c.blocker && c.blocker !== 'none'),
                        (c) => c.blocker, 3),
      askFullyMetPct: calls.length ? Math.round((met / calls.length) * 1000) / 10 : 0,
      askPartiallyMetPct: calls.length ? Math.round((partial / calls.length) * 1000) / 10 : 0,
      resolvedInContactPct: calls.length ? Math.round((resolved / calls.length) * 1000) / 10 : 0,
      highFurtherContactRiskPct: calls.length
        ? Math.round((highRisk / calls.length) * 1000) / 10 : 0,
      coachingThemes: rank(calls, (c) => c.coaching_theme, 3),
      quotes
    };
  })
  .sort((a, b) => b.sampledCalls - a.sampledCalls);

// Customer ask -> what the agent actually provided.
const crossTab = [];
const askGroups = new Map();
for (const c of classifications) {
  const k = c.customer_ask_primary || 'not_stated';
  const e = askGroups.get(k) || [];
  e.push(c);
  askGroups.set(k, e);
}
for (const [ask, calls] of askGroups.entries()) {
  crossTab.push({
    ask,
    askLabel: label(ask),
    count: calls.length,
    pct: n ? Math.round((calls.length / n) * 1000) / 10 : 0,
    provided: rank(calls, (c) => c.agent_provided_primary, 4),
    fullyMetPct: calls.length
      ? Math.round((calls.filter((c) => c.ask_met === 'fully_met').length / calls.length) * 1000) / 10
      : 0
  });
}
crossTab.sort((a, b) => b.count - a.count);

const behaviourCounts = new Map();
for (const c of classifications) {
  for (const b of (c.de_escalation_behaviors || [])) {
    behaviourCounts.set(b, (behaviourCounts.get(b) || 0) + 1);
  }
}

const qualitative = {
  sampledCalls: n,
  avgConfidence: n
    ? Math.round((classifications.reduce((s, c) => s + (Number(c.confidence) || 0), 0) / n) * 100) / 100
    : 0,
  lowConfidenceCalls: classifications.filter((c) => Number(c.confidence) < 0.5).length,
  truncatedTranscripts: classifications.filter((c) => c.transcript_truncated === true).length,
  topTriggers: rank(classifications, (c) => c.escalation_trigger, 12),
  topCustomerAsks: rank(classifications, (c) => c.customer_ask_primary, 12),
  topAgentProvided: rank(classifications, (c) => c.agent_provided_primary, 12),
  askMet: rank(classifications, (c) => c.ask_met),
  resolutionStatus: rank(classifications, (c) => c.resolution_status),
  blockers: rank(classifications.filter((c) => c.blocker && c.blocker !== 'none'),
                 (c) => c.blocker, 10),
  furtherContactRisk: rank(classifications, (c) => c.further_contact_risk),
  concessionRatePct: n
    ? Math.round((classifications.filter((c) => c.concession_given === true).length / n) * 1000) / 10
    : 0,
  observedJourneyMix: rank(classifications, (c) => c.journey_observed, 12),
  deEscalationBehaviors: [...behaviourCounts.entries()]
    .map(([key, count]) => ({ key, label: label(key), count,
                              pct: n ? Math.round((count / n) * 1000) / 10 : 0 }))
    .sort((a, b) => b.count - a.count),
  byJourney,
  crossTab,
  errors: (errorRow && errorRow.classificationErrors) || [],
  tokenUsage: {
    input: classifications.reduce((s, c) => s + (Number(c.input_tokens) || 0), 0),
    output: classifications.reduce((s, c) => s + (Number(c.output_tokens) || 0), 0)
  }
};

return [{ json: { config: cfg, qualitative, classifications } }];

// ---------------------------------------------------------------------------
// Build Report
// Renders the leadership-ready HTML email plus two CSV attachments
// (escalation detail, per-call classifications). Runs whether or not the
// transcript branch executed.
// ---------------------------------------------------------------------------
const cfg = $('Normalize Request').first().json.config;
const summary = $('Summarize Escalations').first().json.summary;

let qualitative = null;
let classifications = [];
try {
  const incoming = $input.first().json;
  if (incoming && incoming.qualitative) {
    qualitative = incoming.qualitative;
    classifications = incoming.classifications || [];
  }
} catch (e) { /* volume-only run */ }

const esc = (v) =>
  String(v === undefined || v === null ? '' : v)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const pct = (v) => (v === undefined || v === null ? '-' : Number(v).toFixed(1) + '%');
const num = (v) => (v === undefined || v === null ? '-' : Number(v).toLocaleString('en-US'));

const TH = 'style="text-align:left;padding:6px 10px;border-bottom:2px solid #7B2E8E;font:600 12px Arial;color:#333"';
const TD = 'style="padding:6px 10px;border-bottom:1px solid #e6e6e6;font:12px Arial;color:#333"';
const H2 = 'style="font:600 15px Arial;color:#7B2E8E;margin:26px 0 8px"';
const P = 'style="font:12px/1.5 Arial;color:#555;margin:0 0 10px"';

const table = (headers, rows) =>
  '<table cellspacing="0" cellpadding="0" style="border-collapse:collapse;width:100%;max-width:820px">' +
  '<tr>' + headers.map((h) => '<th ' + TH + '>' + esc(h) + '</th>').join('') + '</tr>' +
  rows.map((r) => '<tr>' + r.map((c) => '<td ' + TD + '>' + c + '</td>').join('') + '</tr>').join('') +
  '</table>';

const rankTable = (list, headerLabel) =>
  table([headerLabel, 'Calls', 'Share'],
    (list || []).map((r) => [esc(r.label || r.key), num(r.count), pct(r.pct)]));

const parts = [];
parts.push('<div style="font:12px Arial;color:#333;max-width:860px">');
parts.push('<h1 style="font:600 19px Arial;color:#7B2E8E;margin:0 0 4px">' +
  'NA Multi-Contact Escalation Insights</h1>');
parts.push('<p ' + P + '>Window: <b>' + esc(cfg.reportPeriodLabel) + '</b> &middot; Run ID: ' +
  esc(cfg.requestId) + '</p>');

// ---- headline numbers ----
parts.push('<h2 ' + H2 + '>1. Escalation volume (wrap-coded, full population)</h2>');
parts.push(table(
  ['Escalations', 'Distinct orders', 'MC agents', 'Avg/day', 'Resolved in contact', 'Transcript coverage'],
  [[num(summary.totalEscalations), num(summary.distinctOrders), num(summary.distinctMcAgents),
    num(summary.avgPerDay), pct(summary.resolvedInContactPct), pct(summary.transcriptCoveragePct)]]
));

parts.push('<h2 ' + H2 + '>2. What kinds of escalations are coming in</h2>');
parts.push('<p ' + P + '>Journey = the wrap Primary Reason the MC agent selected, per the ' +
  'NA MC Escalation SOP. Resolution rate is the agent-marked ' +
  '<i>customer issue resolved</i> flag on the same wrap.</p>');
parts.push(table(
  ['Journey', 'Escalations', 'Share', 'Resolved in contact', 'Distinct orders', 'Transcript coverage'],
  (summary.byJourney || []).map((j) => [
    esc(j.journey), num(j.count), pct(j.pct), pct(j.resolvedInContactPct),
    num(j.distinctOrders), pct(j.transcriptCoveragePct)
  ])
));

parts.push('<h2 ' + H2 + '>3. Queue, channel and trend</h2>');
parts.push(rankTable(summary.byQueueGroup.map((r) => ({ ...r, label: r.key })), 'Queue group'));
parts.push('<div style="height:10px"></div>');
parts.push(table(['Month', 'Escalations', 'Share'],
  (summary.byMonth || []).map((m) => [esc(m.key), num(m.count), pct(m.pct)])));

// ---- qualitative ----
if (qualitative) {
  parts.push('<h2 ' + H2 + '>4. Why customers escalated (transcript sample, n=' +
    num(qualitative.sampledCalls) + ')</h2>');
  parts.push('<p ' + P + '>Level AI phone transcripts, journey-stratified sample, ' +
    'classified by Claude against a fixed taxonomy. Treat as directional: the sample is ' +
    'stratified by journey, not proportional to volume.</p>');
  parts.push(rankTable(qualitative.topTriggers, 'Escalation trigger'));

  parts.push('<h2 ' + H2 + '>5. What customers asked for</h2>');
  parts.push(rankTable(qualitative.topCustomerAsks, 'Customer ask'));

  parts.push('<h2 ' + H2 + '>6. What agents provided</h2>');
  parts.push(rankTable(qualitative.topAgentProvided, 'Agent resolution'));
  parts.push('<div style="height:10px"></div>');
  parts.push('<p ' + P + '>Concession given on <b>' + pct(qualitative.concessionRatePct) +
    '</b> of sampled calls.</p>');
  parts.push(rankTable(qualitative.askMet, 'Was the ask met?'));

  parts.push('<h2 ' + H2 + '>7. Ask vs. resolution (where the gap is)</h2>');
  parts.push(table(['Customer ask', 'Calls', 'Share', 'Fully met', 'Most common agent response'],
    (qualitative.crossTab || []).map((r) => [
      esc(r.askLabel), num(r.count), pct(r.pct), pct(r.fullyMetPct),
      esc((r.provided || []).map((p) => p.label + ' (' + p.count + ')').join(', '))
    ])));

  parts.push('<h2 ' + H2 + '>8. By journey: trigger, ask, response</h2>');
  for (const j of (qualitative.byJourney || [])) {
    parts.push('<h3 style="font:600 13px Arial;color:#333;margin:18px 0 6px">' +
      esc(j.journey) + ' &middot; ' + num(j.sampledCalls) + ' sampled calls</h3>');
    parts.push(table(['Dimension', 'Top values'], [
      ['Escalation triggers', esc((j.topTriggers || []).map((t) => t.label + ' (' + t.count + ')').join(', '))],
      ['Customer asks', esc((j.topCustomerAsks || []).map((t) => t.label + ' (' + t.count + ')').join(', '))],
      ['Agent provided', esc((j.topAgentProvided || []).map((t) => t.label + ' (' + t.count + ')').join(', '))],
      ['Blockers', esc((j.topBlockers || []).map((t) => t.label + ' (' + t.count + ')').join(', ')) || 'None recorded'],
      ['Ask fully met', pct(j.askFullyMetPct)],
      ['Resolved in contact', pct(j.resolvedInContactPct)],
      ['High risk of further contact', pct(j.highFurtherContactRiskPct)]
    ]));
    if ((j.quotes || []).length) {
      parts.push('<p ' + P + '><i>Customer voice:</i> ' +
        j.quotes.map((q) => '&ldquo;' + esc(q) + '&rdquo;').join(' &middot; ') + '</p>');
    }
  }

  parts.push('<h2 ' + H2 + '>9. Barriers and de-escalation behaviours</h2>');
  parts.push(rankTable(qualitative.blockers, 'Blocker'));
  parts.push('<div style="height:10px"></div>');
  parts.push(rankTable(qualitative.deEscalationBehaviors, 'De-escalation behaviour observed'));
} else {
  parts.push('<h2 ' + H2 + '>4. Transcript analysis</h2>');
  parts.push('<p ' + P + '>Not run for this request (Run Transcript Analysis = No, or no ' +
    'sampled call had a usable Level AI transcript).</p>');
}

// ---- method + caveats ----
parts.push('<h2 ' + H2 + '>Method and caveats</h2>');
parts.push('<ul style="font:12px/1.6 Arial;color:#555;padding-left:18px">');
parts.push('<li>Population: wraps whose <b>Detailed Reason</b> matches ' +
  esc(cfg.escalationDetailPatterns.join(' / ')) + ', submitted by agents on the NA MC roster (' +
  esc(cfg.rosterTeamPatterns.join(' / ')) + '), in MC/CARE queues or with no queue mapping.</li>');
parts.push('<li>Journey mix (section 2) is the full wrap-coded population. Sections 4-9 are a ' +
  'journey-stratified transcript sample of ' + num(qualitative ? qualitative.sampledCalls : 0) +
  ' calls and are directional, not volumetric.</li>');
parts.push('<li>Escalations missed by this method: any escalation the MC agent wrapped with a ' +
  'different Detailed Reason. Unclassified journey share: ' +
  pct(summary.dataQuality.unclassifiedJourneyPct) + '. Unmapped queue share: ' +
  pct(summary.dataQuality.unmappedQueuePct) + '.</li>');
parts.push('<li>Phone transcripts only. Digital escalations (chat/email/SMS) are counted in ' +
  'section 2 but not analyzed in sections 4-9.</li>');
if (qualitative) {
  parts.push('<li>Model: ' + esc(cfg.model) + '. Mean classification confidence ' +
    esc(qualitative.avgConfidence) + '; ' + num(qualitative.lowConfidenceCalls) +
    ' calls below 0.5 confidence; ' + num(qualitative.truncatedTranscripts) +
    ' transcripts truncated at ' + num(cfg.maxTranscriptChars) + ' characters.</li>');
  if ((qualitative.errors || []).length) {
    parts.push('<li><b>' + num(qualitative.errors.length) + ' batch(es) failed to classify</b>: ' +
      esc(qualitative.errors.map((e) => e.reason).join(', ')) + '.</li>');
  }
}
parts.push('</ul>');
parts.push('<p ' + P + '>Attachments: full escalation detail and per-call classifications (CSV).</p>');
parts.push('</div>');

const emailHtml = parts.join('\n');
const emailSubject = 'NA Multi-Contact Escalation Insights | ' + cfg.reportPeriodLabel +
  ' | ' + num(summary.totalEscalations) + ' escalations';

// ---- CSV attachments ----
const csvCell = (v) => {
  const s = v === undefined || v === null ? '' : String(v);
  return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
};
const toCsv = (rows, cols) =>
  [cols.join(',')].concat(rows.map((r) => cols.map((c) => csvCell(r[c])).join(','))).join('\n');

const detailRows = $('GBQ: Escalation Detail').all()
  .map((i) => i.json)
  .filter((r) => r && r.wrap_id !== undefined && r.wrap_id !== null);

const detailCols = ['wrap_date', 'wrap_datetime', 'journey', 'escalation_detail_reason',
  'queue_group', 'queue_name', 'wrap_contact_channel', 'is_customer_issue_resolved',
  'contact_id', 'order_number_final', 'mc_agent_name', 'mc_manager_name', 'mc_team',
  'mc_site', 'levelai_conversation_id', 'asr_log_id', 'levelai_url'];

const classCols = ['contact_id', 'wrap_datetime', 'journey_wrap', 'journey_observed',
  'escalation_trigger', 'escalation_trigger_detail', 'customer_ask_primary',
  'customer_ask_secondary', 'agent_provided_primary', 'agent_provided_detail', 'ask_met',
  'resolution_status', 'concession_given', 'repeat_contacts_mentioned', 'blocker',
  'blocker_detail', 'further_contact_risk', 'further_contact_risk_reason', 'coaching_theme',
  'customer_quote', 'confidence', 'mc_agent_name', 'order_number', 'levelai_url'];

const binary = {
  escalation_detail_csv: {
    data: Buffer.from(toCsv(detailRows, detailCols), 'utf8').toString('base64'),
    mimeType: 'text/csv',
    fileName: 'mc_escalation_detail_' + cfg.windowStart + '_to_' + cfg.windowEnd + '.csv'
  }
};

if (classifications.length) {
  binary.classifications_csv = {
    data: Buffer.from(toCsv(classifications, classCols), 'utf8').toString('base64'),
    mimeType: 'text/csv',
    fileName: 'mc_escalation_classifications_' + cfg.windowStart + '_to_' + cfg.windowEnd + '.csv'
  };
}

return [{
  json: {
    config: cfg,
    recipientEmail: cfg.recipientEmail,
    emailSubject,
    emailHtml,
    hasClassifications: classifications.length > 0,
    attachmentProperties: Object.keys(binary).join(',')
  },
  binary
}];
